#!/usr/bin/env bash
# Weekly MazingiraKenya Narrative-Disinfo queue — 2026-10-19
# Queues UNPUBLISHED drafts (published=false) into Supabase disinfo_items for admin review.
# This run wrote the 4 drafts via a connected Chrome (POST /rest/v1/disinfo_items, 201) because
# the Mac device-bridge shell cannot reach supabase.co (proxy / HTTP 000 — 403 from CONNECT proxy).
# This script reproduces the same inserts anywhere Supabase IS reachable, via insert-disinfo-draft.mjs.
#   Usage: bash scripts/queue-disinfo-2026-10-19.sh
set -euo pipefail
cd "$(dirname "$0")/.."

node scripts/insert-disinfo-draft.mjs '{"name":"Circulating in carbon-market / clean-cooking promotion","posted_at":"2026-10-19","body":"Kenya'"'"'s clean-cooking carbon market was a model climate-finance success — firms like KOKO Networks genuinely cut millions of tonnes of emissions by switching households from charcoal to clean cookstoves, exactly as their carbon credits claimed.","verdict":"Greenwashing / misleading framing","verdict_class":"vm","source_url":"https://www.downtoearth.org.in/africa/kenyas-latest-carbon-credit-crackdown-reveals-questionable-practices-players-sneaky-ways","source_label":"Down To Earth · Kenya carbon-credit crackdown (KOKO Networks)","rebuttal":"The \"exactly as claimed\" story is contradicted by Kenya'"'"'s own carbon-market crackdown. Regulators declined to grant KOKO Networks a required Letter of Authorization over the volume of credits it planned to sell, and the company — after 11 years — collapsed into administration in 2026. Independent analysis of its clean-cooking credits found the climate benefit was badly overstated: KOKO is reported to have used a 93% non-renewable-biomass fraction when the realistic rate for Nairobi is around 38% (inflating credits by more than 2.4x), assumed households previously burned only charcoal while ignoring LPG and other fuels, and extrapolated usage from a 159-household survey despite tracking every litre of fuel sold digitally. The ratings agency BeZero graded the credits only B overall (low likelihood of delivering a full tonne of CO2 removal) and D for carbon accounting. These are the same integrity problems flagged across Kenya'"'"'s carbon market — inflated baselines and overstated reductions — so clean-cooking offsets should be treated as unproven until verified against real fuel-sales and survival data."}'

node scripts/insert-disinfo-draft.mjs '{"name":"Circulating on social media","posted_at":"2026-10-19","body":"Claims that climate change is bad for people'"'"'s health are exaggerated — climate change is not actually having a negative impact on global health.","verdict":"Climate denial (health impacts minimised)","verdict_class":"vf","source_url":"https://pesacheck.org/false-it-is-untrue-that-climate-change-is-not-negatively-impacting-global-health/","source_label":"PesaCheck · climate-and-health fact-check","rebuttal":"This is false. Major health bodies document clear, growing harm. The World Health Organization expects climate change to cause roughly 250,000 additional deaths per year between 2030 and 2050 from malnutrition, malaria, diarrhoeal disease and heat stress, and the annual Lancet Countdown reports rising heat-related deaths, longer transmission seasons and widening ranges for mosquito-borne diseases such as malaria and dengue. The effects are already visible in East Africa: warmer, wetter conditions push malaria into highland areas of Kenya, Ethiopia and Rwanda that were historically too cool for it; recurrent drought in the Horn of Africa drives acute malnutrition; and floods — like Kenya'"'"'s 2026 flooding — spread cholera and other waterborne illness while destroying clinics and crops. Saying climate change has no negative health impact contradicts the WHO, the IPCC and the published medical literature."}'

node scripts/insert-disinfo-draft.mjs '{"name":"Circulating in oil-industry / EACOP promotion","posted_at":"2026-10-19","body":"TotalEnergies is a major player in the energy transition, and its East African oil projects — the EACOP pipeline and Tilenga field in Uganda — are being developed responsibly and are compatible with climate goals.","verdict":"Greenwashing / misleading framing","verdict_class":"vm","source_url":"https://ugbusiness.com/2025/11/energy-oil-gas/environment/totalenergies-greenwashing-verdict-opens-new-front-for-african-climate-litigation","source_label":"Paris court greenwashing ruling · African climate litigation","rebuttal":"A court has already found this framing misleading. In October 2025 the Paris Judicial Court ruled TotalEnergies guilty of misleading commercial practices — the first time a fossil-fuel major was judicially sanctioned for greenwashing. The court held that advertising describing the company as a major player in the energy transition, and its net-zero-by-2050 pledge, gave consumers a false impression of climate action while the company keeps expanding oil and gas production and its emissions rise. It was ordered to stop the ads and publish the ruling. The same responsible / transition-aligned branding is used for the East African Crude Oil Pipeline (EACOP) and Tilenga, which independent analysts and rights groups tie to large projected lifetime emissions, displacement and compensation complaints affecting tens of thousands of people, and routes near sensitive areas such as the Lake Victoria basin and Murchison Falls — with litigation ongoing in East Africa and the UK. A heated crude-export pipeline built to open new oil fields is not evidence of an energy transition; independent verification, not corporate branding, should decide whether a project is climate-compatible."}'

node scripts/insert-disinfo-draft.mjs '{"name":"Circulating on social media (#FossilFuelsForAfrica cluster)","posted_at":"2026-10-19","body":"Climate action is green colonialism — a Western agenda to keep Africa poor by denying it the right to use its own oil and gas. Africa contributes almost nothing to emissions, so it should burn its fossil fuels to develop and ignore foreign climate demands.","verdict":"Needs context / false dilemma","verdict_class":"vc","source_url":"https://toxic10.investigate.africa/","source_label":"Code for Africa · ClimateWatch Toxic 10 investigation","rebuttal":"This mixes a real grievance with a false choice. It is true that Africa has contributed only about 3-4% of cumulative global emissions yet suffers some of the worst impacts, and that demands for climate finance and a fair, well-funded transition are legitimate. But the fossil-fuels-or-poverty framing is a false dilemma: in most African markets new solar and wind are now cheaper per kilowatt-hour than new fossil generation, so clean energy is increasingly the faster route to expanding access, not an obstacle to it. Code for Africa'"'"'s ClimateWatch Toxic 10 investigation documents that the green-colonialism / keep-Africa-poor narrative is heavily amplified by fossil-fuel-funded and opaque dark-money actors — among them the African Energy Chamber and the #FossilFuelsForAfrica network — precisely to delay climate action and lock in oil and gas. Genuine energy-justice arguments deserve a hearing; using them to insist Africa must burn fossil fuels, while downplaying that the continent is among the hardest hit by warming, serves the industry more than African development."}'

echo "Queued 4 disinfo drafts (2026-10-19) — awaiting admin review."
